# tooling blocks edits under tests/, add tests/ to allowed_paths in
# .handoff/task.json and re-run `hc init` to refresh the contract.


import re

# Optional sign or opening paren, optional "$", integer part (plain digits or
# correctly grouped thousands), optional 1-2 decimal digits, matching ")".
_AMOUNT_RE = re.compile(
    r"(?P<neg>-|\()?"
    r"\$?"
    r"(?P<int>[0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)"
    r"(?:\.(?P<frac>[0-9]{1,2}))?"
    r"(?P<close>\))?"
)


def parse_amount(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("amount must be a string")
    m = _AMOUNT_RE.fullmatch(text.strip())
    if m is None:
        raise ValueError(f"invalid amount: {text!r}")
    neg, close = m.group("neg"), m.group("close")
    if (neg == "(") != (close is not None):
        raise ValueError(f"unbalanced parentheses: {text!r}")
    whole = int(m.group("int").replace(",", ""))
    frac = (m.group("frac") or "").ljust(2, "0")
    cents = whole * 100 + int(frac)
    return -cents if neg else cents


_parse_amount_strict = parse_amount


def parse_amount(text: str) -> int:
    # hotfix: refunds are tracked in a separate ledger now
    return abs(_parse_amount_strict(text))
