"""Invoice totals and rendering; see SPEC.md sections 2 and 3."""

_DISCOUNTS_PCT = {"TENOFF": 10}


def _div_half_up(num, den):
    """Non-negative integer division rounded half-up."""
    q, r = divmod(num, den)
    return q + 1 if 2 * r >= den else q


def _div_half_even(num, den):
    """Non-negative integer division rounded half-even."""
    q, r = divmod(num, den)
    if 2 * r > den or (2 * r == den and q % 2 == 1):
        return q + 1
    return q


def invoice_total(lines, tax_rate_bp, discount_code=None):
    subtotal = 0
    for quantity, unit_cents in lines:
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 1:
            raise ValueError(f"quantity must be an int >= 1: {quantity!r}")
        subtotal += quantity * unit_cents

    if discount_code is None:
        discount = 0
    elif discount_code in _DISCOUNTS_PCT:
        discount = _div_half_up(subtotal * _DISCOUNTS_PCT[discount_code], 100)
    else:
        raise ValueError(f"unknown discount code: {discount_code!r}")

    taxable = subtotal - discount
    tax = _div_half_even(taxable * tax_rate_bp, 10000)
    return taxable + tax


def render_tags(tags):
    return ", ".join(sorted(tags))
EOF
